def compute(vars):
    principal_redeemed = vars["v1"]
    annual_interest_rate = vars["v2"]
    annual_interest_cost_savings = principal_redeemed * annual_interest_rate * 0.01

    return {
        "value": annual_interest_cost_savings,
        "trace": {
            "principal_redeemed": principal_redeemed,
            "annual_interest_rate_percent": annual_interest_rate,
            "annual_interest_cost_savings": annual_interest_cost_savings,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "currency"
            }
        }
    }
